16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "customer_code")
71	    private String customerCode;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "bulk_signup_warning")
83	    private Boolean bulkSignupWarning;
84	
85	    @Column(name = "capacity_warning")
86	    private Boolean capacityWarning;
87	
88	    @Column(name = "household_size")
89	    private Integer householdSize;
90	
91	    @Column(name = "postcode")
92	    private String postcode;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @Column(name = "membership_level_cap")
98	    private Integer membershipLevelCap;
99	
100	    @Column(name = "deleted", nullable = false)
101	    private boolean deleted;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    public String getTitle() {
107	        return this.title;
108	    }
109	
110	    public void setTitle(String title) {
111	        this.title = title;
112	    }
113	
114	    public String getAddress() {
115	        return this.address;
116	    }
117	
118	    public void setAddress(String address) {
119	        this.address = address;
120	    }
121	
122	    /**
123	     * The first line of this owner's structured postal address, or {@code null} when the owner was
124	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
125	     * present; see {@link #getAddress()} for the composed form.
126	     */
127	    public String getAddressLine1() {
128	        return this.addressLine1;
129	    }
130	
131	    public void setAddressLine1(String addressLine1) {
132	        this.addressLine1 = addressLine1;
133	    }
134	
135	    /**
136	     * The optional second line of this owner's structured postal address, or {@code null} when none
137	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
138	     * composed {@link #getAddress() address}.
139	     */
140	    public String getAddressLine2() {
141	        return this.addressLine2;
142	    }
143	
144	    public void setAddressLine2(String addressLine2) {
145	        this.addressLine2 = addressLine2;
146	    }
147	
148	    public String getCity() {
149	        return this.city;
150	    }
151	
152	    public void setCity(String city) {
153	        this.city = city;
154	    }
155	
156	    public String getTelephone() {
157	        return this.telephone;
158	    }
159	
160	    public void setTelephone(String telephone) {
161	        this.telephone = telephone;
162	    }
163	
164	    /**
165	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
166	     * as the calling code, a space, then the national digits grouped in threes, e.g.
167	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
168	     */
169	    @Transient
170	    public String getTelephoneDisplay() {
171	        return TelephoneFormatter.toDisplay(this.telephone);
172	    }
173	
174	    public String getEmail() {
175	        return this.email;
176	    }
177	
178	    public void setEmail(String email) {
179	        this.email = email;
180	    }
181	
182	    public LocalDate getRegistrationDate() {
183	        return this.registrationDate;
184	    }
185	
186	    public void setRegistrationDate(LocalDate registrationDate) {
187	        this.registrationDate = registrationDate;
188	    }
189	
190	    /**
191	     * Return this owner's fiscal year, formatted {@code FY<YY>}, derived from the (business-day
192	     * adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is named by the
193	     * calendar year in which it ends. {@code null} when no registration date is known.
194	     */
195	    @Transient
196	    public String getFiscalYear() {
197	        return this.registrationDate == null ? null : FiscalYear.of(this.registrationDate).getLabel();
198	    }
199	
200	    public LocalDate getBirthDate() {
201	        return this.birthDate;
202	    }
203	
204	    public void setBirthDate(LocalDate birthDate) {
205	        this.birthDate = birthDate;
206	    }
207	
208	    public String getCustomerCode() {
209	        return this.customerCode;
210	    }
211	
212	    public void setCustomerCode(String customerCode) {
213	        this.customerCode = customerCode;
214	    }
215	
216	    /**
217	     * Return this owner's current primary identifier: the single value that identifies the owner in
218	     * external audit events. Currently the {@link #getCustomerCode() customer code}; when the customer
219	     * code is unified into the membership number this will return that instead, so callers that only
220	     * need "the owner's identifier" stay correct across that change.
221	     */
222	    @Transient
223	    public String getPrimaryIdentifier() {
224	        return this.customerCode;
225	    }
226	
227	    public String getHouseholdId() {
228	        return this.householdId;
229	    }
230	
231	    public void setHouseholdId(String householdId) {
232	        this.householdId = householdId;
233	    }
234	
235	    public Integer getNamesakeCount() {
236	        return this.namesakeCount;
237	    }
238	
239	    public void setNamesakeCount(Integer namesakeCount) {
240	        this.namesakeCount = namesakeCount;
241	    }
242	
243	    public String getMembershipNumber() {
244	        return this.membershipNumber;
245	    }
246	
247	    public void setMembershipNumber(String membershipNumber) {
248	        this.membershipNumber = membershipNumber;
249	    }
250	
251	    /**
252	     * Whether this owner was created after more than 80 owners had already been registered on the
253	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
254	     */
255	    public Boolean getBulkSignupWarning() {
256	        return this.bulkSignupWarning;
257	    }
258	
259	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
260	        this.bulkSignupWarning = bulkSignupWarning;
261	    }
262	
263	    /**
264	     * Whether this owner's city had already reached the capacity-warning band (at least 40 but fewer
265	     * than the hard limit of 50 owners) when this owner was created, flagging that the city is
266	     * approaching its capacity limit. Captured once at creation.
267	     */
268	    public Boolean getCapacityWarning() {
269	        return this.capacityWarning;
270	    }
271	
272	    public void setCapacityWarning(Boolean capacityWarning) {
273	        this.capacityWarning = capacityWarning;
274	    }
275	
276	    /**
277	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
278	     * counting this owner) captured once at creation.
279	     */
280	    public Integer getHouseholdSize() {
281	        return this.householdSize;
282	    }
283	
284	    public void setHouseholdSize(Integer householdSize) {
285	        this.householdSize = householdSize;
286	    }
287	
288	    /**
289	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
290	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
291	     */
292	    public String getPostcode() {
293	        return this.postcode;
294	    }
295	
296	    public void setPostcode(String postcode) {
297	        this.postcode = postcode;
298	    }
299	
300	    /**
301	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
302	     * creation, or {@code null} when none. Set at creation when an existing owner shares this
303	     * owner's {@code soundex(lastName)} and postcode but has a different {@link #getIdentityKey()
304	     * identity key} (e.g. a different telephone), so the two are not a hard duplicate. Captured
305	     * once at creation.
306	     */
307	    public Integer getPossibleDuplicateOf() {
308	        return this.possibleDuplicateOf;
309	    }
310	
311	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
312	        this.possibleDuplicateOf = possibleDuplicateOf;
313	    }
314	
315	    /**
316	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
317	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
318	     */
319	    @Transient
320	    public Boolean getPossibleDuplicate() {
321	        return this.possibleDuplicateOf != null;
322	    }
323	
324	    /**
325	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
326	     * the highest membership level among the household members that already existed when this owner
327	     * was created, or {@code null} when the owner joined no existing household and is therefore
328	     * uncapped. Captured once at creation.
329	     */
330	    public Integer getMembershipLevelCap() {
331	        return this.membershipLevelCap;
332	    }
333	
334	    public void setMembershipLevelCap(Integer membershipLevelCap) {
335	        this.membershipLevelCap = membershipLevelCap;
336	    }
337	
338	    /**
339	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an owner
340	     * flags it {@code true} and retains the record rather than removing it. Duplicate and identity
341	     * checks at creation ignore owners flagged deleted.
342	     */
343	    public boolean isDeleted() {
344	        return this.deleted;
345	    }
346	
347	    public void setDeleted(boolean deleted) {
348	        this.deleted = deleted;
349	    }
350	
351	    /**
352	     * Return this owner's canonical API path, being {@code "/api/owners/"} followed by this owner's
353	     * {@link #getId() id}.
354	     */
355	    @Transient
356	    public String getSelfLink() {
357	        return "/api/owners/" + this.getId();
358	    }
359	
360	    /**
361	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
362	     */
363	    @Transient
364	    public String getDisplayName() {
365	        return this.getLastName() + ", " + this.getFirstName();
366	    }
367	
368	    /**
369	     * Return this owner's salutation as the {@link #getTitle() title} and last name separated by a
370	     * space (e.g. {@code "DR Who"}), or just the last name when no title was supplied.
371	     */
372	    @Transient
373	    public String getSalutation() {
374	        return (this.title == null || this.title.isBlank())
375	            ? this.getLastName()
376	            : this.title + " " + this.getLastName();
377	    }
378	
379	    /**
380	     * Return this owner's initials as the upper-cased first letters of the first and last
381	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
382	     */
383	    @Transient
384	    public String getInitials() {
385	        return initial(this.getFirstName()) + initial(this.getLastName());
386	    }
387	
388	    private static String initial(String name) {
389	        return Character.toUpperCase(name.charAt(0)) + ".";
390	    }
391	
392	    /** Points awarded when an email address is present. */
393	    private static final int EMAIL_POINTS = 2;
394	
395	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
396	    private static final int NO_NAMESAKE_POINTS = 1;
397	
398	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
399	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
400	
401	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
402	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
403	
404	    /** Points awarded for qualifying tenure. */
405	    private static final int TENURE_POINTS = 3;
406	
407	    /** The tenure, in elapsed fiscal years, that must be exceeded to earn {@link #TENURE_POINTS}. */
408	    private static final long MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS = 1;
409	
410	    /**
411	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
412	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
413	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
414	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
415	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed fiscal year since registration).
416	     */
417	    @Transient
418	    public Integer getMembershipPoints() {
419	        int points = 0;
420	        if (hasEmail()) {
421	            points += EMAIL_POINTS;
422	        }
423	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
424	            points += NO_NAMESAKE_POINTS;
425	        }
426	        if (hasLargeHousehold()) {
427	            points += LARGE_HOUSEHOLD_POINTS;
428	        }
429	        if (hasQualifyingTenure()) {
430	            points += TENURE_POINTS;
431	        }
432	        return points;
433	    }
434	
435	    /**
436	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
437	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then limited to the
438	     * owner's {@link #getMembershipLevelCap() membership-level ceiling} when one applies.
439	     */
440	    @Transient
441	    public Integer getMembershipLevel() {
442	        int level = membershipLevelFromPoints();
443	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
444	            return this.membershipLevelCap;
445	        }
446	        return level;
447	    }
448	
449	    /** Map this owner's {@link #getMembershipPoints() membership points} to the uncapped level. */
450	    private int membershipLevelFromPoints() {
451	        int points = getMembershipPoints();
452	        if (points <= 1) {
453	            return 1;
454	        }
455	        if (points <= 3) {
456	            return 2;
457	        }
458	        if (points <= 5) {
459	            return 3;
460	        }
461	        return 4;
462	    }
463	
464	    /**
465	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
466	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
467	     * qualify.
468	     */
469	    private boolean hasLargeHousehold() {
470	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
471	    }
472	
473	    /**
474	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed
475	     * fiscal year, i.e. more than that many fiscal years have elapsed between the fiscal year of the
476	     * {@code registrationDate} and the fiscal year of today. Owners without a registration date have
477	     * no measurable tenure and do not qualify.
478	     */
479	    private boolean hasQualifyingTenure() {
480	        if (this.registrationDate == null) {
481	            return false;
482	        }
483	        long elapsedFiscalYears = FiscalYear.of(this.registrationDate).yearsUntil(FiscalYear.of(LocalDate.now()));
484	        return elapsedFiscalYears > MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS;
485	    }
486	
487	    /** Whether this owner has a usable email address (present and not blank). */
488	    private boolean hasEmail() {
489	        return this.email != null && !this.email.isBlank();
490	    }
491	
492	    /**
493	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
494	     * present, otherwise {@code "PHONE"}.
495	     */
496	    @Transient
497	    public String getContactPreference() {
498	        return hasEmail() ? "EMAIL" : "PHONE";
499	    }
500	
501	    /**
502	     * Return this owner's age band derived from the {@code birthDate} as of the
503	     * {@code registrationDate}, or {@code null} when no birth date is known.
504	     */
505	    @Transient
506	    public AgeBand getAgeBand() {
507	        if (this.birthDate == null || this.registrationDate == null) {
508	            return null;
509	        }
510	        return AgeBand.asOf(this.birthDate, this.registrationDate);
511	    }
512	
513	    /**
514	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
515	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
516	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
517	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
518	     * region is resolved directly from the postcode and city.
519	     */
520	    @Transient
521	    public String getLocality() {
522	        if (this.customerCode == null) {
523	            return LocalityResolver.regionFor(this.postcode, this.city);
524	        }
525	        int separator = this.customerCode.indexOf('-');
526	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
527	    }
528	
529	    /**
530	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
531	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
532	     * known timezone.
533	     */
534	    @Transient
535	    public String getTimezone() {
536	        return LocalityResolver.timezoneFor(getLocality());
537	    }
538	
539	    /**
540	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
541	     * {@code customerCode}.
542	     */
543	    @Transient
544	    public Integer getCheckDigit() {
545	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
546	    }
547	
548	    /**
549	     * Return this owner's identity key, the single derived value all duplicate detection is based
550	     * on: the lower-case SHA-256 hex digest over {@code normalizedTelephone + "|" + lowerEmail +
551	     * "|" + soundex(lastName)}, with an absent email rendered as the empty string. Two owners are
552	     * duplicates only when their whole identity keys are equal; because the telephone is part of
553	     * the key, two owners with the same last name and postcode but different telephones have
554	     * distinct keys and are not duplicates (they are instead flagged as a soft match).
555	     */
556	    @Transient
557	    public String getIdentityKey() {
558	        String core = keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + Soundex.encode(this.getLastName());
559	        return Sha256Hex.lowerHex(core);
560	    }
561	
562	    private static String keyPart(String value) {
563	        return value == null ? "" : value;
564	    }
565	
566	    protected Set<Pet> getPetsInternal() {
567	        if (this.pets == null) {
568	            this.pets = new HashSet<>();
569	        }
570	        return this.pets;
571	    }
572	
573	    protected void setPetsInternal(Set<Pet> pets) {
574	        this.pets = pets;
575	    }
576	
577	    public List<Pet> getPets() {
578	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
579	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
580	        return Collections.unmodifiableList(sortedPets);
581	    }
582	
583	    public void setPets(List<Pet> pets) {
584	        this.pets = new HashSet<>(pets);
585	    }
586	
587	    public void addPet(Pet pet) {
588	        getPetsInternal().add(pet);
589	        pet.setOwner(this);
590	    }
591	
592	    /**
593	     * Return the Pet with the given name, or null if none found for this Owner.
594	     *
595	     * @param name to test
596	     * @return true if pet name is already in use
597	     */
598	    public Pet getPet(String name) {
599	        return getPet(name, false);
600	    }
601	
602	    /**
603	     * Return the Pet with the given name, or null if none found for this Owner.
604	     *
605	     * @param name to test
606	     * @return true if pet name is already in use
607	     */
608	    public Pet getPet(String name, boolean ignoreNew) {
609	        name = name.toLowerCase();
610	        for (Pet pet : getPetsInternal()) {
611	            if (!ignoreNew || !pet.isNew()) {
612	                String compName = pet.getName();
613	                compName = compName.toLowerCase();
614	                if (compName.equals(name)) {
615	                    return pet;
616	                }
617	            }
618	        }
619	        return null;
620	    }
621	
622	    public Pet getPet(Integer petId) {
623	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
624	    }
625	
626	    @Override
627	    public String toString() {
628	        return new ToStringCreator(this)
629	
630	            .append("id", this.getId())
631	            .append("new", this.isNew())
632	            .append("lastName", this.getLastName())
633	            .append("firstName", this.getFirstName())
634	            .append("address", this.address)
635	            .append("city", this.city)
636	            .append("telephone", this.telephone)
637	            .append("email", this.email)
638	            .append("registrationDate", this.registrationDate)
639	            .toString();
640	    }
641	}
