15	 */
16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Resolves an owner's locality (canonical region) from their postcode and city. The postcode is
22	 * preferred: a postcode falling within a known region's range determines the region directly, which
23	 * disambiguates cities that share a name. Only when the postcode is absent or in no known range does
24	 * resolution fall back to the fixed city-to-region table. Inputs matching neither resolve to
25	 * {@link #UNKNOWN}.
26	 */
27	public final class LocalityResolver {
28	
29	    /** Locality returned when neither the postcode nor the city yields a region. */
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private static final Map<String, String> CITY_REGIONS = Map.of(
33	        "Sydney", "NSW",
34	        "Melbourne", "VIC",
35	        "Brisbane", "QLD");
36	
37	    /** Region -> inclusive four-digit postcode range {@code {low, high}}. */
38	    private static final Map<String, int[]> REGION_RANGES = Map.of(
39	        "NSW", new int[] {2000, 2099},
40	        "VIC", new int[] {3000, 3099},
41	        "QLD", new int[] {4000, 4099});
42	
43	    /** Region -> IANA timezone name. */
44	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
45	        "NSW", "Australia/Sydney",
46	        "VIC", "Australia/Melbourne",
47	        "QLD", "Australia/Brisbane");
48	
49	    private LocalityResolver() {
50	    }
51	
52	    /**
53	     * Resolve the canonical region, preferring the postcode over the city.
54	     *
55	     * @param postcode the postcode to look up first, or {@code null}/absent
56	     * @param city     the city used as a fallback when the postcode yields no region
57	     * @return the region determined by the postcode's range, or failing that by the
58	     *         city-to-region table, or {@link #UNKNOWN} when neither matches
59	     */
60	    public static String regionFor(String postcode, String city) {
61	        String byPostcode = regionForPostcode(postcode);
62	        return byPostcode != null ? byPostcode : regionForCity(city);
63	    }
64	
65	    /**
66	     * Resolve the canonical region for the given city via the fixed city-to-region table.
67	     *
68	     * @param city the city to look up
69	     * @return the region string, or {@link #UNKNOWN} when the city is not in the table
70	     */
71	    public static String regionForCity(String city) {
72	        return CITY_REGIONS.getOrDefault(city, UNKNOWN);
73	    }
74	
75	    /**
76	     * The IANA timezone name for the given region via the fixed region-to-timezone table.
77	     *
78	     * @param region the region to look up
79	     * @return the IANA timezone name, or {@code null} when the region has no known timezone
80	     */
81	    public static String timezoneFor(String region) {
82	        return REGION_TIMEZONES.get(region);
83	    }
84	
85	    /**
86	     * The inclusive four-digit postcode range for the given region.
87	     *
88	     * @param region the region to look up
89	     * @return a fresh {@code {low, high}} array, or {@code null} when the region has no range
90	     */
91	    public static int[] rangeForRegion(String region) {
92	        int[] range = REGION_RANGES.get(region);
93	        return range == null ? null : range.clone();
94	    }
95	
96	    /**
97	     * The region whose postcode range contains the given postcode.
98	     *
99	     * @param postcode the postcode to classify, or {@code null}/absent
100	     * @return the matching region, or {@code null} when the postcode is absent, not a number, or in
101	     *         no known range
102	     */
103	    private static String regionForPostcode(String postcode) {
104	        if (postcode == null) {
105	            return null;
106	        }
107	        int value;
108	        try {
109	            value = Integer.parseInt(postcode.trim());
110	        }
111	        catch (NumberFormatException ex) {
112	            return null;
113	        }
114	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
115	            int[] range = entry.getValue();
116	            if (value >= range[0] && value <= range[1]) {
117	                return entry.getKey();
118	            }
119	        }
120	        return null;
121	    }
122	}
